1	//! Saga 21 step 001: REST surface integration
2	//! tests. Spin `mlpl-serve` up on a random localhost
3	//! port via `server::build_app(...)` + a manual
4	//! `axum::serve(listener, app)`, then drive it with
5	//! `reqwest`.
6	
7	use std::net::SocketAddr;
8	
9	use mlpl_serve::auth::AuthMode;
10	use mlpl_serve::server::{ServerError, build_app, build_app_with_peers, run};
11	use serde_json::Value as JsonValue;
12	
13	/// Spin up a server in the background on a random
14	/// loopback port. Returns the bound address; the
15	/// task runs for the duration of the test.
16	async fn start_server(auth_mode: AuthMode) -> SocketAddr {
17	    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
18	    let addr = listener.local_addr().unwrap();
19	    let app = build_app(auth_mode);
20	    tokio::spawn(async move {
21	        axum::serve(listener, app).await.unwrap();
22	    });
23	    addr
24	}
25	
26	async fn create_session(addr: SocketAddr) -> (String, String) {
27	    let resp = reqwest::Client::new()
28	        .post(format!("http://{addr}/v1/sessions"))
29	        .send()
30	        .await
31	        .unwrap();
32	    assert_eq!(resp.status(), 200, "session create should be 200");
33	    let body: JsonValue = resp.json().await.unwrap();
34	    let id = body["session_id"].as_str().unwrap().to_string();
35	    let token = body["token"].as_str().unwrap().to_string();
36	    assert!(!id.is_empty(), "session_id must be non-empty");
37	    assert!(!token.is_empty(), "token must be non-empty");
38	    (id, token)
39	}
40	
41	#[tokio::test]
42	async fn post_sessions_returns_id_and_token() {
43	    let addr = start_server(AuthMode::Required).await;
44	    let (id, token) = create_session(addr).await;
45	    // 32 alphanumeric is the contract; check both the
46	    // length and that no two sessions reuse a token.
47	    assert_eq!(token.len(), 32, "token should be 32 chars");
48	    let (id2, token2) = create_session(addr).await;
49	    assert_ne!(id, id2, "session ids must be unique");
50	    assert_ne!(token, token2, "tokens must be unique");
51	}
52	
53	#[tokio::test]
54	async fn eval_runs_program_against_session_env() {
55	    let addr = start_server(AuthMode::Required).await;
56	    let (id, token) = create_session(addr).await;
57	
58	    let resp = reqwest::Client::new()
59	        .post(format!("http://{addr}/v1/sessions/{id}/eval"))
60	        .bearer_auth(&token)
61	        .json(&serde_json::json!({"program": "iota(5)"}))
62	        .send()
63	        .await
64	        .unwrap();
65	    assert_eq!(resp.status(), 200);
66	    let body: JsonValue = resp.json().await.unwrap();
67	    assert_eq!(body["kind"], "array", "iota returns an array");
68	    let value = body["value"].as_str().unwrap();
69	    // iota(5) prints as something containing 0..4 in
70	    // some bracketed form; we don't pin the exact
71	    // formatting, but the digits must be there.
72	    for digit in ['0', '1', '2', '3', '4'] {
73	        assert!(
74	            value.contains(digit),
75	            "iota(5) value {value:?} should contain digit {digit}"
76	        );
77	    }
78	}
79	
80	#[tokio::test]
81	async fn eval_persists_state_across_calls() {
82	    let addr = start_server(AuthMode::Required).await;
83	    let (id, token) = create_session(addr).await;
84	    let url = format!("http://{addr}/v1/sessions/{id}/eval");
85	    let client = reqwest::Client::new();
86	
87	    // First call binds `x = 7` (assignment returns
88	    // a sentinel; we don't care about the value).
89	    let r1 = client
90	        .post(&url)
91	        .bearer_auth(&token)
92	        .json(&serde_json::json!({"program": "x = 7"}))
93	        .send()
94	        .await
95	        .unwrap();
96	    assert_eq!(r1.status(), 200);
97	
98	    // Second call reads `x` -- proves the env
99	    // survived between requests.
100	    let r2 = client
101	        .post(&url)
102	        .bearer_auth(&token)
103	        .json(&serde_json::json!({"program": "x"}))
104	        .send()
105	        .await
106	        .unwrap();
107	    assert_eq!(r2.status(), 200);
108	    let body: JsonValue = r2.json().await.unwrap();
109	    assert!(
110	        body["value"].as_str().unwrap().contains('7'),
111	        "second eval should see x=7 from the first call"
112	    );
113	}
