//! Router wiring + server entry. Saga 21 step 001.

use std::net::SocketAddr;

use axum::Router;
use axum::routing::{get, post};
use mlpl_array::DenseArray;
use mlpl_eval::{EvalError, PeerDispatcher, Value};
use serde::{Deserialize, Serialize};

use crate::auth::AuthMode;
use crate::handlers::{create_session_handler, eval_handler, health_handler, inspect_handler};
use crate::peers::{PeerRegistry, PeerSessionMap};
use crate::sessions::{SessionMap, new_map};

/// Errors the server can fail with at startup or
/// while serving. Translated to stderr + non-zero
/// exit by `main`.
#[derive(Debug)]
pub enum ServerError {
    /// `--bind 0.0.0.0` (or any non-loopback) without
    /// `--auth required`.
    InsecureBind { addr: SocketAddr },
    /// Failed to bind the listener socket.
    Bind(std::io::Error),
    /// Axum `serve` returned an error.
    Serve(std::io::Error),
}

impl std::fmt::Display for ServerError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InsecureBind { addr } => write!(
                f,
                "refusing to bind {addr} with --auth disabled: \
                 non-loopback addresses require --auth required"
            ),
            Self::Bind(e) => write!(f, "bind failed: {e}"),
            Self::Serve(e) => write!(f, "serve failed: {e}"),
        }
    }
}

impl std::error::Error for ServerError {}

/// Shared state on the application: the session map,
/// the peer registry (Saga R1 step 003), and the
/// configured auth mode.
#[derive(Clone)]
pub struct AppState {
    pub sessions: SessionMap,
    pub peers: PeerRegistry,
    pub peer_sessions: PeerSessionMap,
    pub auth_mode: AuthMode,
}

#[derive(Debug)]
pub struct RemoteMlxDispatcher {
    peers: PeerRegistry,
    sessions: PeerSessionMap,
}

#[derive(Serialize)]
pub struct EvalOnDeviceBinding {
    pub name: String,
    pub tensor: String,
}

#[derive(Serialize)]
struct EvalOnDeviceRequest {
    program: String,
    bindings: Vec<EvalOnDeviceBinding>,
}

#[derive(Deserialize)]
struct EvalOnDeviceResponse {
    result: EvalResultPayload,
}

#[derive(Deserialize)]
#[serde(tag = "kind", rename_all = "lowercase")]
enum EvalResultPayload {
    Tensor {
        handle: String,
        shape: Vec<usize>,
        device: String,
    },
    String {
        value: String,
    },
}

#[derive(Deserialize)]
struct TransferResponse {
    tensor: String,
}

impl RemoteMlxDispatcher {
    #[must_use]
    pub fn new(peers: PeerRegistry, sessions: PeerSessionMap) -> Self {
        Self { peers, sessions }
    }
}

impl PeerDispatcher for RemoteMlxDispatcher {
    #[rustfmt::skip]
    fn dispatch_block(
        &self,
        device: &str,
        source: &str,
        bindings: std::collections::HashMap<String, DenseArray>,
    ) -> Option<Result<Value, EvalError>> {
        let peer = self.peers.get(device)?.clone();
        let session = self.sessions.get_or_create(&peer);
        let bindings = crate::peers::encode_bindings(bindings);
        let (session, bindings) = match (session, bindings) {
            (Ok(session), Ok(bindings)) => (session, bindings),
            (Err(e), _) | (_, Err(e)) => return Some(Err(e)),
        };
        let body = EvalOnDeviceRequest { program: source.to_string(), bindings };
        let url = format!(
            "{}/v1/sessions/{}/eval-on-device",
            peer.url.trim_end_matches('/'),
            session.id
        );
        let client = peer.client;
        let token = session.token;
        let result = std::thread::spawn(move || {
            client
                .post(url)
                .bearer_auth(&token)
                .json(&body)
                .send()
                .and_then(reqwest::blocking::Response::error_for_status)?
                .json::<EvalOnDeviceResponse>()
        })
        .join()
        .map_err(|_| EvalError::Unsupported("remote peer thread panicked".into()));
        Some(result.and_then(|r| {
            r.map_err(|e| EvalError::Unsupported(format!("remote peer request: {e}")))
        }).map(|r| match r.result {
            EvalResultPayload::Tensor { handle, shape, device } => {
                Value::DeviceTensor { peer: peer.url, handle, shape, device }
            }
            EvalResultPayload::String { value } => Value::Str(value),
        }))
    }

    fn fetch_tensor(&self, peer_url: &str, handle: &str) -> Result<DenseArray, EvalError> {
        let peer = self
            .peers
            .values()
            .find(|p| p.url == peer_url)
            .ok_or_else(|| EvalError::Unsupported(format!("unknown peer {peer_url}")))?;
        let session = self.sessions.get_or_create(peer)?;
        let url = format!(
            "{}/v1/sessions/{}/transfer",
            peer.url.trim_end_matches('/'),
            session.id
        );
        let client = peer.client;
        let token = session.token;
        let handle = handle.to_string();
        let resp = std::thread::spawn(move || {
            client
                .post(url)
                .bearer_auth(&token)
                .json(&serde_json::json!({ "handle": handle }))
                .send()
                .and_then(reqwest::blocking::Response::error_for_status)?
                .json::<TransferResponse>()
        })
        .join()
        .map_err(|_| EvalError::Unsupported("remote peer thread panicked".into()))?
        .map_err(|e| EvalError::Unsupported(format!("remote peer request: {e}")))?;
        crate::peers::decode_from_json(&resp.tensor)
    }
}

/// Build the axum router with the session-map state
/// and auth mode wired in. Empty peer registry; use
/// `build_app_with_peers` for tests that need to
/// register peers up-front.
pub fn build_app(auth_mode: AuthMode) -> Router {
    build_app_with_peers(auth_mode, crate::peers::empty_registry(), None)
}

/// Saga R1 step 003 + Saga 25 step A: build the
/// router with an explicit peer registry and an
/// optional static-asset directory. Used by `run` and
/// by integration tests; `static_dir = None` keeps
/// the legacy API-only behavior.
pub fn build_app_with_peers(
    auth_mode: AuthMode,
    peers: crate::peers::PeerRegistry,
    static_dir: Option<&std::path::Path>,
) -> Router {
    let state = AppState {
        sessions: new_map(),
        peers,
        peer_sessions: PeerSessionMap::default(),
        auth_mode,
    };
    let mut router = Router::new()
        .route("/v1/health", get(health_handler))
        .route("/v1/sessions", post(create_session_handler))
        .route("/v1/sessions/:id/eval", post(eval_handler))
        .route("/v1/sessions/:id/inspect", get(inspect_handler))
        .with_state(state);
    if let Some(dir) = static_dir {
        // The web build sets `--public-url /sw-mlpl/`, so
        // every asset reference in `pages/index.html` is
        // already prefixed with `/sw-mlpl/`. Mount the
        // ServeDir on that exact prefix so the same
        // committed `pages/` directory works locally and
        // on GitHub Pages without rebuilding.
        let serve = tower_http::services::ServeDir::new(dir);
        router = router.nest_service("/sw-mlpl", serve);
    }
    router
}

/// Bind the listener at `addr`, refuse insecure
/// non-loopback binds, then `axum::serve` the
/// router. Used by `main`; tests call `build_app`
/// directly + run on their own listener.
///
/// Saga R1 step 003: `peers` carries the
/// `--peer mlx=<url>`-derived registry built up by
/// `peers::build_registry` in `main`. An empty
/// registry means "no peer routing; device-scoped
/// blocks fall back to in-process dispatch."
/// Optional TLS configuration. `None` keeps the legacy
/// HTTP path; `Some(config)` switches to
/// `axum_server::bind_rustls` so the same listener
/// terminates TLS for the /v1 API and the static UI.
pub type TlsConfig = Option<axum_server::tls_rustls::RustlsConfig>;

pub async fn run(
    addr: SocketAddr,
    auth_mode: AuthMode,
    peers: crate::peers::PeerRegistry,
    static_dir: Option<std::path::PathBuf>,
    tls: TlsConfig,
) -> Result<(), ServerError> {
    if !addr.ip().is_loopback() && auth_mode == AuthMode::Disabled {
        return Err(ServerError::InsecureBind { addr });
    }
    let app = build_app_with_peers(auth_mode, peers, static_dir.as_deref());
    match tls {
        Some(config) => axum_server::bind_rustls(addr, config)
            .serve(app.into_make_service())
            .await
            .map_err(ServerError::Bind),
        None => {
            let listener = tokio::net::TcpListener::bind(addr)
                .await
                .map_err(ServerError::Bind)?;
            axum::serve(listener, app).await.map_err(ServerError::Serve)
        }
    }
}

//! Evaluation environment (variable bindings).

use std::collections::{HashMap, HashSet};
use std::path::PathBuf;
use std::sync::Arc;

use mlpl_array::DenseArray;
use mlpl_core::ValueTag;

use crate::error::EvalError;
use crate::experiment::ExperimentRecord;
use crate::grad::OptimizerState;
use crate::model::ModelSpec;
use crate::tokenizer::TokenizerSpec;
use crate::value::Value;

/// Orchestrator hook for remote device peers. Implemented by
/// `mlpl-serve`; absent in local REPL / web eval, where device blocks
/// fall back to the in-process path.
pub trait PeerDispatcher: Send + Sync + std::fmt::Debug {
    fn dispatch_block(
        &self,
        _device: &str,
        _source: &str,
        _bindings: HashMap<String, DenseArray>,
    ) -> Option<Result<Value, EvalError>> {
        None
    }

    fn fetch_tensor(&self, peer: &str, _handle: &str) -> Result<DenseArray, EvalError> {
        Err(EvalError::Unsupported(format!(
            "no peer dispatcher can fetch tensor from {peer}"
        )))
    }
}

/// Variable bindings for evaluation.
#[derive(Clone, Debug, Default)]
pub struct Environment {
    pub(crate) vars: HashMap<String, DenseArray>,
    pub(crate) params: HashSet<String>,
    /// Saga 15 step 001: parameters that are still trainable
    /// (in `params`) and still carry values but that
    /// `adam` / `momentum_sgd` must skip at the
    /// optimizer-update stage. Gradient computation is
    /// unaffected -- the chain rule still flows through
    /// frozen parameters; only the *update* is suppressed.
    pub(crate) frozen_params: HashSet<String>,
    pub(crate) optim_state: OptimizerState,
    pub(crate) models: HashMap<String, ModelSpec>,
    pub(crate) next_model_id: u64,
    /// Tokenizer bindings (Saga 12 step 004). Sibling to `models`.
    pub(crate) tokenizers: HashMap<String, TokenizerSpec>,
    /// Sandbox root for filesystem `load("relative-path")` calls.
    /// `None` means filesystem access is disabled (the web REPL
    /// surface, where `std::fs` doesn't exist under WASM). Saga 12
    /// step 001.
    pub(crate) data_dir: Option<PathBuf>,
    /// String-valued variable bindings (Saga 12 step 009). Sibling
    /// to `vars`; populated when assignment value is a `Value::Str`
    /// (e.g. `corpus = load_preloaded("...")`). Ident lookup checks
    /// here before falling through to array vars.
    pub(crate) strings: HashMap<String, String>,
    /// Output directory for `experiment` records. `None` disables
    /// disk writes (web REPL); `Some(path)` is set by the terminal
    /// REPL's `--exp-dir` flag. Saga 12 step 007.
    pub(crate) exp_dir: Option<PathBuf>,
    /// Append-only log of completed experiments in this env.
    pub(crate) experiment_log: Vec<ExperimentRecord>,
    /// Stack of active `device("...")` targets. Empty stack means
    /// the implicit CPU device. The innermost (last) entry wins,
    /// so nested `device("mlx") { device("cpu") { ... } }` runs
    /// the inner body on CPU even when the outer is MLX. Saga 14
    /// step 004.
    pub(crate) device_stack: Vec<String>,
    /// Per-tensor device placement. Saga 14 step 005: `to_device`
    /// records the target here keyed by the tensor's variable
    /// name. Missing keys default to `"cpu"`. Params allocated
    /// inside a `device("mlx") { }` block are pre-stamped with
    /// `"mlx"` by the model constructors so `apply(model, X)` can
    /// cross-check placement without the caller needing to remember
    /// to call `to_device` on every param.
    pub(crate) tensor_device: HashMap<String, String>,
    /// One-time-warning flag for the "user asked for MLX but the
    /// mlx feature is not compiled in" fallback path. Set on the
    /// first `device("mlx") { }` entry under that condition; the
    /// warning is emitted at most once per `Environment`.
    pub(crate) mlx_fallback_warned: bool,
    /// Optional remote peer dispatcher installed by the orchestrator
    /// around one eval call. Local eval leaves this unset.
    pub(crate) peer_dispatcher: Option<Arc<dyn PeerDispatcher>>,
    /// Peer-resident tensor handles bound by assignment.
    pub(crate) device_tensors: HashMap<String, Value>,
    /// Saga 23 step 001: optional ValueTag attached per binding
    /// name. Auto-tagged by producer ops in steps 002+; consumed
    /// by predicate-checked consumers, `:describe` / `:vars` /
    /// `:tags`, and trace JSON. Re-binding a name with a new tag
    /// overwrites; clearing is explicit via `clear_tag`. Untyped
    /// bindings keep working unchanged (gradual-typing
    /// additivity rule).

