1	//! In-memory session storage. Saga 21 step 001.
2	//!
3	//! `Session` owns a fresh `mlpl_eval::Environment`;
4	//! the eval handler holds a write lock on the map
5	//! for the duration of the eval call (because
6	//! `Environment` is mutated by side-effecting
7	//! builtins). A future saga can swap the storage
8	//! to disk-backed for persistence.
9	
10	use std::collections::HashMap;
11	use std::sync::Arc;
12	
13	use mlpl_eval::Environment;
14	use rand::Rng;
15	use rand::distributions::Alphanumeric;
16	use tokio::sync::RwLock;
17	use uuid::Uuid;
18	
19	const TOKEN_LEN: usize = 32;
20	
21	/// One client session. Holds the bearer token and a
22	/// long-lived `Environment` that accumulates state
23	/// across eval calls.
24	pub struct Session {
25	    pub token: String,
26	    pub env: Environment,
27	}
28	
29	/// Shared state on the application: maps session ids
30	/// to sessions. `Arc<RwLock<...>>` so axum handlers
31	/// can clone cheaply while serializing writes.
32	pub type SessionMap = Arc<RwLock<HashMap<Uuid, Session>>>;
33	
34	/// Construct a fresh empty session map.
35	#[must_use]
36	pub fn new_map() -> SessionMap {
37	    Arc::new(RwLock::new(HashMap::new()))
38	}
39	
40	/// Create a new session, insert it into the map,
41	/// return the id + token. Caller is responsible for
42	/// surfacing both back to the client.
43	pub async fn create_session(map: &SessionMap) -> (Uuid, String) {
44	    let id = Uuid::new_v4();
45	    let token = generate_token();
46	    let session = Session {
47	        token: token.clone(),
48	        env: Environment::new(),
49	    };
50	    map.write().await.insert(id, session);
51	    (id, token)
52	}
53	
54	/// 32 alphanumeric characters from the thread-local
55	/// CSPRNG. ~190 bits of entropy; enough for the
56	/// loopback / LAN threat model. A future saga can
57	/// swap in `OsRng` + a longer alphabet if the
58	/// threat model changes.
59	fn generate_token() -> String {
60	    rand::thread_rng()
61	        .sample_iter(&Alphanumeric)
62	        .take(TOKEN_LEN)
63	        .map(char::from)
64	        .collect()
65	}
