    fn spawn_eval_task(
        id: Uuid,
        mut session: crate::sessions::Session,
        stmts: Vec<mlpl_parser::Expr>,
        sessions_map: crate::sessions::SessionMap,
        tx: mpsc::Sender<SseEvent>,
    ) {
