                Ok(v) => SseEvent::Done {
                    value: format!("{v}"),
                    kind: value_kind(&v),
                },
                Err(e) => SseEvent::Error {
                    error: format!("{e}"),
                },
            };
            let _ = tx.send(terminal).await;
            sessions_map.write().await.insert(id, session);
        });
    }

